// Собираем результаты запросов к GitHub
const issuesData = $('Fetch Issues Last 7 Days').all().map(item => item.json);
const pullsData = $('Fetch PRs Last 7 Days').all().map(item => item.json);

// Определяем границы календарной недели (строго с Понедельника 00:00 по Воскресенье 23:59 UTC)
const now = new Date();
const dayOfWeek = now.getUTCDay(); // 0 = вс, 1 = пн, 2 = вт, ..., 6 = сб

let weekStart = new Date(now);
let weekEnd = new Date(now);

if (dayOfWeek === 1) {
  // Запуск в понедельник (штатный крон 09:00): отчёт за прошлую завершённую календарную неделю
  weekStart.setUTCDate(now.getUTCDate() - 7);
  weekEnd.setUTCDate(now.getUTCDate() - 1);
} else {
  // Тестовый запуск посреди недели: отчёт за текущую календарную неделю (Пн — Вс)
  const daysSinceMonday = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
  weekStart.setUTCDate(now.getUTCDate() - daysSinceMonday);
  weekEnd.setUTCDate(weekStart.getUTCDate() + 6);
}

weekStart.setUTCHours(0, 0, 0, 0);
weekEnd.setUTCHours(23, 59, 59, 999);

let bugsCount = 0;
let featuresCount = 0;
let tasksCount = 0;
let triageCount = 0;
let totalIssues = 0;
const authorMap = {};
const seenIssues = new Set();

// Обработка Issues (фильтруем PR и исключаем дубликаты)
for (const item of issuesData) {
  if (!item || !item.number) continue;
  if (item.pull_request) continue; // В /issues API GitHub возвращает и PR, пропускаем их
  if (seenIssues.has(item.number)) continue;
  seenIssues.add(item.number);

  const createdAt = new Date(item.created_at);
  if (createdAt >= weekStart && createdAt <= weekEnd) {
    totalIssues++;
    const labels = (item.labels || []).map(l => (typeof l === 'string' ? l : l.name).toLowerCase());

    if (labels.includes('bug')) bugsCount++;
    if (labels.includes('feature')) featuresCount++;
    if (labels.includes('task')) tasksCount++;
    if (labels.includes('needs-triage')) triageCount++;

    const author = item.user ? item.user.login : 'unknown';
    authorMap[author] = (authorMap[author] || 0) + 1;
  }
}

// Обработка PRs (строго уникальные PR по номеру)
let prsCount = 0;
const seenPrs = new Set();
for (const pr of pullsData) {
  if (!pr || !pr.number || seenPrs.has(pr.number)) continue;
  seenPrs.add(pr.number);

  const createdAt = new Date(pr.created_at);
  if (createdAt >= weekStart && createdAt <= weekEnd) {
    prsCount++;
    const author = pr.user ? pr.user.login : 'unknown';
    authorMap[author] = (authorMap[author] || 0) + 1;
  }
}

// Топ автор
let topAuthor = 'Vyvch';
let maxContributions = 0;
for (const [author, count] of Object.entries(authorMap)) {
  if (count > maxContributions) {
    maxContributions = count;
    topAuthor = author;
  }
}

const startStr = weekStart.toISOString().slice(0, 10);
const endStr = weekEnd.toISOString().slice(0, 10);

return {
  json: {
    week_id: `week_${startStr}`,
    total_issues: totalIssues,
    bugs_count: bugsCount,
    features_count: featuresCount,
    tasks_count: tasksCount,
    triage_count: triageCount,
    prs_count: prsCount,
    top_author: topAuthor,
    authors_breakdown: authorMap,
    week_start: startStr,
    week_end: endStr
  }
};

const current = $('Group Statistics (Types & Authors)').first().json;
let previous = {};

try {
  const prevRows = $('Get Previous Week Stats').all();
  if (prevRows && prevRows.length > 0) {
    previous = prevRows[prevRows.length - 1].json;
  }
} catch (e) {}

function formatDelta(curr, prev) {
  if (typeof prev !== 'number') return '(new)';
  const diff = curr - prev;
  if (diff > 0) return `+${diff}`;
  if (diff < 0) return `${diff}`;
  return '0';
}

const deltaIssues = formatDelta(current.total_issues, previous.total_issues);
const deltaBugs = formatDelta(current.bugs_count, previous.bugs_count);
const deltaFeatures = formatDelta(current.features_count, previous.features_count);
const deltaTasks = formatDelta(current.tasks_count, previous.tasks_count);
const deltaPrs = formatDelta(current.prs_count, previous.prs_count);

return {
  json: {
    ...current,
    prev_total_issues: previous.total_issues || 0,
    prev_bugs_count: previous.bugs_count || 0,
    delta_issues: deltaIssues,
    delta_bugs: deltaBugs,
    delta_features: deltaFeatures,
    delta_tasks: deltaTasks,
    delta_prs: deltaPrs
  }
};
